// ════════════════════════════════════════════════════════════
// NODE DETAILS — Enriched 4-section format for all 65 nodes
// ════════════════════════════════════════════════════════════

const nodeDetails = {

  // ── TIER 0 — Schema Setup ──

  admin_signup: `<h3>How It Works</h3><p>Admin signs up via web dashboard with email + password. Cognito handles authentication with email verification, password reset, and optional MFA.</p><h3>User Experience</h3><ul><li>Admin visits signup page, enters email + password</li><li>Verification email sent, must click link</li><li>After verification, redirected to org creation</li></ul><h3>Data Flow</h3><p>Browser → Cognito signup → email verification → JWT issued → stored in browser. <code>User { id, email, name, cognitoSub }</code></p><h3>Design Decisions</h3><ul><li>Cognito for managed auth — no custom password infrastructure</li><li>Email verification required before org creation</li><li>Social login (Google) planned for faster onboarding</li></ul>`,

  create_org: `<h3>How It Works</h3><p>First-time admin creates their org with name, type, and settings. Provisions the org in the database and creates the admin's membership with full permissions.</p><h3>User Experience</h3><ul><li>Admin enters org name, selects industry type</li><li>System auto-generates slug for branding URLs</li><li>Redirected to dashboard with full admin access</li></ul><h3>Data Flow</h3><p>Signup JWT → API → create <code>Organization { name, slug, settings }</code> + <code>Membership { userId, orgId, role: ADMIN }</code>. Org.id becomes the tenant scope for all subsequent data.</p><h3>Design Decisions</h3><ul><li>Org is the top-level tenant — all data scoped via orgId</li><li>Multi-org support: users can belong to multiple orgs via Memberships</li><li>Org slug used for branding and URLs</li></ul>`,

  subscription: `<h3>How It Works</h3><p>After org creation, admin selects a plan via Stripe Checkout. Manages subscription lifecycle: trial, active, past_due, cancelled. Usage-based billing for Captures beyond plan limits.</p><h3>User Experience</h3><ul><li>Admin selects plan tier from pricing page</li><li>Stripe Checkout handles payment securely</li><li>Customer Portal for self-serve plan changes and invoices</li></ul><h3>Data Flow</h3><p>Dashboard → Stripe Checkout → webhook → <code>Organization.stripeCustomerId</code> + <code>Subscription { plan, status }</code>. Usage metered via Stripe Meter API per CaptureSession.</p><h3>Design Decisions</h3><ul><li>Stripe for managed billing — Customer Portal for self-serve</li><li>Plans: Starter (50 Captures/mo), Pro (500), Enterprise (unlimited)</li><li>Usage metering via Stripe Meter API</li></ul>`,

  form_builder: `<h3>How It Works</h3><p>Admin builds Schemas using a drag-and-drop editor, or selects from a template library. Schemas define what data gets Captured — Fields, sections, conditional logic, and validation rules. Supports PDF/Word import via OCR.</p><h3>User Experience</h3><ul><li>Drag-and-drop Field placement into sections</li><li>Configure per-Field: type, importance weight, key terms, validation</li><li>Preview Schema as Participant would see it</li><li>Import existing PDF documents via OCR auto-detection</li></ul><h3>Data Flow</h3><p>Admin edits → <code>Schema { orgId, name, version, schema }</code> → <code>Field[] { label, type, options, order, required, importance, keyTerms }</code>. Schema feeds AI Extraction prompts.</p><h3>Design Decisions</h3><ul><li>Drag-and-drop Schema Builder in dashboard</li><li>Template library for common Schema types (EPS, general, safety)</li><li>Schemas are versioned — editing doesn't affect past CaptureSessions</li><li>Field types: text, number, select, photo, signature, date, GPS</li></ul>`,

  form_ingestion: `<h3>How It Works</h3><p>Import existing PDF or Word documents. OCR engine detects Field labels, types, and structure, then auto-creates Fields from uploaded documents. Admin reviews and adjusts detected Fields.</p><h3>User Experience</h3><ul><li>Upload PDF or paste web form URL</li><li>System highlights detected Fields with confidence scores</li><li>Admin confirms, adjusts, or removes detected Fields</li><li>One-click import into Schema Builder</li></ul><h3>Data Flow</h3><p>Upload → OCR engine → <code>DocumentImport { sourceType, file, detectedFields[] }</code> → admin review → <code>Field[]</code> creation in Schema Builder.</p><h3>Design Decisions</h3><ul><li>OCR via Textract or GPT-4o vision for Field detection</li><li>Human-in-the-loop: never auto-publish imported Schemas</li><li>Supports multi-page PDFs and tabular layouts</li></ul>`,

  form_templates: `<h3>How It Works</h3><p>Pre-built Schema templates for common types. Admin clones a template and customizes it for their org. Also ingests external documents as starting points.</p><h3>User Experience</h3><ul><li>Browse template library by category</li><li>Preview template before cloning</li><li>One-click clone → opens in Schema Builder for customization</li></ul><h3>Data Flow</h3><p><code>SchemaTemplate { name, category, schema }</code> → clone → <code>Schema { isTemplate: false, orgId }</code>. Templates maintained by PAX team.</p><h3>Design Decisions</h3><ul><li>Categories: EPS / Pest Control, Property, Safety, General</li><li>Community templates planned for marketplace</li><li>Templates versioned independently from org Schemas</li></ul>`,

  form_markdown_guidance: `<h3>How It Works</h3><p>Markdown documents per Schema that describe mapping rules, Field expectations, examples, and context. These are fed directly to the AI during Extraction to improve accuracy.</p><h3>User Experience</h3><ul><li>Admin writes or uploads markdown guidance per Schema</li><li>Includes Field mapping hints and example values</li><li>AI references this context during Extraction</li></ul><h3>Data Flow</h3><p>Admin edits → <code>SchemaGuidance { schemaId, markdownContent, examples[], fieldMappingHints }</code> → injected into AI Extraction prompt alongside Schema.</p><h3>Design Decisions</h3><ul><li>Markdown for maximum flexibility — supports rich examples</li><li>Per-Schema, not per-Field, to keep management simple</li><li>Versioned alongside Schema versions</li></ul>`,

  form_versioning: `<h3>How It Works</h3><p>Every edit to a published Schema creates a new version. Past CaptureSessions always reference their original Schema version. Publishing a new version makes it the default for new CaptureSessions.</p><h3>User Experience</h3><ul><li>Admin edits Schema in draft mode</li><li>Publishes when ready — creates immutable snapshot</li><li>Can view version history and diff changes</li></ul><h3>Data Flow</h3><p>Edit → draft → publish → <code>Schema.version</code> incremented → <code>Field[]</code> snapshot frozen. Past <code>CaptureSession</code> references keep original version.</p><h3>Design Decisions</h3><ul><li>Immutable snapshots on publish</li><li>Draft mode for in-progress edits</li><li>Version diffing for admin review</li></ul>`,

  setup_properties: `<h3>How It Works</h3><p>Admin defines Destinations (properties/sites) that get inspected. Each Destination has an address, GPS coordinates, and is linked to a client Person. Destinations are the "where" of Captures.</p><h3>User Experience</h3><ul><li>Add Destination with address autocomplete (Google Places)</li><li>Link to client contact from Person list</li><li>View on map with GPS pin</li></ul><h3>Data Flow</h3><p>Admin input → <code>Destination { orgId, address, gps, clientPersonId }</code>. GPS from Google Places API. Destination.id used in <code>Assignment</code> records.</p><h3>Design Decisions</h3><ul><li>Google Places API for address autocomplete</li><li>GPS coordinates for map view and routing</li><li>Client linkage via Person entity (not User)</li></ul>`,

  license_management: `<h3>How It Works</h3><p>Enterprise orgs get company codes for batch employee onboarding. Admins generate license codes, set seat limits, and track usage. Alternative to individual email invites for large teams.</p><h3>User Experience</h3><ul><li>Admin generates license code with seat limit and expiry</li><li>Shares code with team via email, Slack, or print</li><li>Dashboard shows seats used vs. available</li></ul><h3>Data Flow</h3><p>Admin creates → <code>License { orgId, code, maxSeats, usedSeats, expiresAt }</code>. Participant enters code → validates → creates <code>Membership</code>.</p><h3>Design Decisions</h3><ul><li>Codes are short alphanumeric strings, easy to share verbally</li><li>Seat-based licensing for enterprise billing model</li><li>Codes can be revoked or expired by admin</li></ul>`,

  assign_numbers: `<h3>How It Works</h3><p>Each org gets a dedicated Twilio phone number for voice Captures. Admin provisions and assigns numbers from the dashboard.</p><h3>User Experience</h3><ul><li>Admin clicks "Provision Number" in settings</li><li>System auto-selects local number from Twilio inventory</li><li>Number displayed for sharing with Participants</li></ul><h3>Data Flow</h3><p>Admin request → Twilio API → <code>TwilioNumber { phoneNumber, orgId, sid }</code> → <code>Organization.twilioPhoneNumber</code> updated.</p><h3>Design Decisions</h3><ul><li>Twilio number provisioned via API — $1/mo per number</li><li>Call routing: Twilio webhook → API → CaptureSession creation</li><li>Multiple numbers per org for different regions (future)</li></ul>`,

  integration_settings: `<h3>How It Works</h3><p>Configure connections to third-party systems: CRMs, property management software, compliance databases. Webhook endpoints for real-time event delivery. Visible API endpoints with delivery status tracking.</p><h3>User Experience</h3><ul><li>Configure webhook URLs with event filtering</li><li>Generate and manage API keys</li><li>View delivery status and retry failed webhooks</li><li>One-click Salesforce/ServiceNow connector setup</li></ul><h3>Data Flow</h3><p>Admin config → <code>Integration { orgId, provider, config }</code> + <code>WebhookEndpoint { url, events[], secret }</code> + <code>APIEndpoint { orgId, path, status }</code>.</p><h3>Design Decisions</h3><ul><li>Webhook configuration with event filtering</li><li>API key management for programmatic access</li><li>OAuth integrations for partner platforms</li></ul>`,

  field_configuration: `<h3>How It Works</h3><p>Per-Field configuration beyond basic type/label: importance weighting for completeness scoring, descriptive text for AI context, key terms for Extraction, and custom validation rules.</p><h3>User Experience</h3><ul><li>Click any Field in Schema Builder → advanced config panel</li><li>Set importance weight (0–1) for completeness scoring</li><li>Add key terms and descriptive text for AI Extraction hints</li><li>Define validation rules (regex, range, enum)</li></ul><h3>Data Flow</h3><p><code>FieldConfig { fieldId, importance, keyTerms[], validationRules, descriptiveText }</code> → fed into AI Extraction prompt + quality validation checks.</p><h3>Design Decisions</h3><ul><li>Importance weighting drives completeness % calculation</li><li>Key terms help AI match transcript phrases to Fields</li><li>Validation rules run both client-side and server-side</li></ul>`,

  output_configuration: `<h3>How It Works</h3><p>Per-Schema output configuration: target format (CSV, JSON, PDF), external system mapping, and a visual flow editor for routing Schema Fields to output targets.</p><h3>User Experience</h3><ul><li>Select output format per Schema (PDF, CSV, JSON, webhook)</li><li>Visual drag-and-drop editor: map Schema Fields → output columns</li><li>Preview output with sample data before saving</li></ul><h3>Data Flow</h3><p><code>OutputConfig { schemaId, format, template, targetSystem, fieldMapping[] }</code> → drives PDF generation, CSV export, and external system Fulfillment.</p><h3>Design Decisions</h3><ul><li>Visual flow editor for non-technical admins</li><li>Per-Schema, not per-org — different Schemas can have different outputs</li><li>Field transformation rules (e.g., date formatting, unit conversion)</li></ul>`,

  vocabulary_aliases: `<h3>How It Works</h3><p>Company-wide or Schema-specific term aliases and vocabulary packages. Maps informal shorthand, acronyms, and regional terms to canonical values for consistent AI Extraction.</p><h3>User Experience</h3><ul><li>Admin adds aliases: "LTN" → "Lifetime North"</li><li>Select industry vocabulary packages (pest control, HVAC, etc.)</li><li>AI uses aliases during transcription → Field mapping</li></ul><h3>Data Flow</h3><p><code>Alias { orgId, schemaId?, canonical, variants[] }</code> + <code>VocabularyPackage { orgId, industry, terms[] }</code> → fed to Field normalization and AI Extraction.</p><h3>Design Decisions</h3><ul><li>Company-wide aliases apply to all Schemas unless overridden</li><li>Industry vocabulary packages pre-built by PAX</li><li>Aliases improve Extraction accuracy significantly for domain-specific terms</li></ul>`,

  feature_toggles: `<h3>How It Works</h3><p>Per-org default feature configuration: photo markup enabled/disabled, captioning mode, default CaptureMode (camera vs transcript), tagging behavior. Users can override with personal preferences.</p><h3>User Experience</h3><ul><li>Admin configures org-wide defaults in settings</li><li>Toggle features on/off for all Participants</li><li>Participants can override some settings in their preferences</li></ul><h3>Data Flow</h3><p><code>OrgFeatureConfig { orgId, markupEnabled, captioningMode, defaultCaptureMode }</code> → merged with <code>UserPreference</code> overrides at runtime.</p><h3>Design Decisions</h3><ul><li>Org defaults as baseline, user overrides for flexibility</li><li>Feature toggles control UI visibility and AI behavior</li><li>Gradual rollout: enable features per-org before global release</li></ul>`,

  // ── TIER 1 — Participant Onboarding ──

  invite_team: `<h3>How It Works</h3><p>Admin sends email invites to Participants. Each invite creates a pending Membership. Participant receives a magic link to claim their account and auto-join the org.</p><h3>User Experience</h3><ul><li>Admin enters email addresses, selects role</li><li>Bulk invite via CSV upload or one-by-one</li><li>Track invite status: sent, opened, claimed</li></ul><h3>Data Flow</h3><p>Admin submits → <code>Invite { email, orgId, role, token, expiresAt }</code> → SES email → magic link → <code>Membership { status: PENDING → ACTIVE }</code>.</p><h3>Design Decisions</h3><ul><li>Role-based: Admin, Participant, Viewer</li><li>Invite link expires after 7 days, re-invite available</li><li>Cross-org support: Participant with existing account merges memberships</li></ul>`,

  inspector_claims: `<h3>How It Works</h3><p>Participant gets email with magic link. One click creates their account (or links to existing) and auto-joins the org with Participant role. Mobile-first experience.</p><h3>User Experience</h3><ul><li>Click magic link in email</li><li>Auto-creates account or links existing</li><li>Redirected to app download or phone number display</li></ul><h3>Data Flow</h3><p>Magic link → validate token → create <code>User { email, phone, cognitoSub }</code> → update <code>Membership { status: ACTIVE, joinedAt }</code>.</p><h3>Design Decisions</h3><ul><li>Magic link preferred over manual signup — lowest friction</li><li>Link works in mobile browser, redirects to app if installed</li><li>Zero-training target: Participant should complete first Capture in under 15 minutes</li></ul>`,

  license_code_entry: `<h3>How It Works</h3><p>Participant enters a company code to join an enterprise org. Alternative to magic link invite — useful for large teams where individual invites are impractical.</p><h3>User Experience</h3><ul><li>Open app → "Join with Code" option</li><li>Enter alphanumeric code provided by employer</li><li>Instant org join with Participant role</li></ul><h3>Data Flow</h3><p>Code input → validate <code>License.code</code> → check seats remaining → create <code>User</code> + <code>Membership</code> → increment <code>License.usedSeats</code>.</p><h3>Design Decisions</h3><ul><li>Alternative to email invites for enterprise scale</li><li>Codes can be printed on job site posters</li><li>Seat limit enforcement prevents unauthorized access</li></ul>`,

  gets_app: `<h3>How It Works</h3><p>Two paths: (1) Download Expo app for full-featured Captures with camera, GPS, offline support, or (2) Just get the org's phone number for voice-only Captures. Shows default Schema on first launch.</p><h3>User Experience</h3><ul><li>Deep link from invite → app store download</li><li>First launch shows default Schema assignment</li><li>Can request access to additional Schemas from admin</li></ul><h3>Data Flow</h3><p>Invite/code → app install → JWT auth → load <code>Membership</code> → display <code>Organization.twilioPhoneNumber</code> + assigned Schemas.</p><h3>Design Decisions</h3><ul><li>Phone MVP — works on any phone, zero install friction</li><li>App adds: photos in context, GPS, offline, Schema preview</li><li>Deep link from invite email → app store or phone display</li></ul>`,

  user_preferences: `<h3>How It Works</h3><p>Per-user settings: default Schema, preferred CaptureMode, notification preferences, and feature toggle overrides. Merges with org-level defaults.</p><h3>User Experience</h3><ul><li>Settings screen in app</li><li>Select default Schema for quick-start</li><li>Choose CaptureMode: camera-first vs voice-first</li><li>Configure push notification preferences</li></ul><h3>Data Flow</h3><p><code>UserPreference { userId, defaultSchemaId, captureMode, notificationPrefs, featureOverrides }</code> → merged with <code>OrgFeatureConfig</code> at runtime. User overrides win.</p><h3>Design Decisions</h3><ul><li>User preferences override org defaults for flexibility</li><li>Stored server-side for cross-device consistency</li><li>Synced to local storage for offline access</li></ul>`,

  training: `<h3>How It Works</h3><p>Guided first-Capture walkthrough. Demo Schema, practice call, tips and best practices. Goal: Participant can do a real Capture within 15 minutes of claiming their invite.</p><h3>User Experience</h3><ul><li>Interactive demo CaptureSession in sandbox mode</li><li>Voice prompt practice for phone path</li><li>Photo capture tips for quality images</li><li>Progress tracker shows completion</li></ul><h3>Data Flow</h3><p>Training module → sandbox <code>CaptureSession</code> (not saved to real data) → completion flag on <code>User</code> profile.</p><h3>Design Decisions</h3><ul><li>Interactive demo preferred over video tutorials</li><li>Sandbox mode — no real data affected</li><li>Skip option for experienced Participants</li></ul>`,

  ready_inspect: `<h3>How It Works</h3><p>Checkpoint: Participant has everything needed — app installed or phone number saved, Schema assignments in queue, understanding of the process. Admin can push new Schema access from dashboard.</p><h3>User Experience</h3><ul><li>Dashboard shows readiness checklist</li><li>Green checkmarks for completed setup steps</li><li>Assignment queue visible and ready</li></ul><h3>Data Flow</h3><p>Readiness = has <code>Membership(ACTIVE)</code> + has app or phone + has <code>Assignment[]</code> in queue. Admin can push Schema access via dashboard.</p><h3>Design Decisions</h3><ul><li>Readiness is a computed state, not a stored field</li><li>Admins notified if Participant hasn't completed setup</li><li>Gentle reminders via push notification</li></ul>`,

  // ── TIER 2 — Capture Trigger ──

  scheduler: `<h3>How It Works</h3><p>Automated recurring Captures based on schedules. Calendar-based triggers create assignments automatically at defined intervals (weekly, monthly, quarterly).</p><h3>User Experience</h3><ul><li>Admin creates schedule: Schema + Destination + frequency</li><li>Calendar view shows upcoming auto-Captures</li><li>Auto-assignment to available Participants</li></ul><h3>Data Flow</h3><p><code>Schedule { schemaId, orgId, frequency, nextRun }</code> → cron trigger → auto-create <code>Assignment</code> → push notification to assigned Participant.</p><h3>Design Decisions</h3><ul><li>Recurring schedules per Destination/Schema type</li><li>Auto-assignment to available Participants (round-robin)</li><li>Calendar sync (Google Calendar, Outlook) planned</li></ul>`,

  admin_assigns: `<h3>How It Works</h3><p>Admin assigns a CaptureSession to a specific Participant. Assignment includes Schema selection, Destination details, deadline, and special instructions. Triggers push notification. Supports ticket-based assignment from external systems.</p><h3>User Experience</h3><ul><li>Select Participant, Schema, Destination from dropdowns</li><li>Set deadline and add notes</li><li>Participant gets immediate push notification</li><li>Bulk assignment for multiple Destinations</li></ul><h3>Data Flow</h3><p>Admin action → <code>Assignment { orgId, userId, schemaId, destinationId, deadline, notes }</code> → push notification via <code>PushToken</code> → appears in Participant's queue.</p><h3>Design Decisions</h3><ul><li>Push notification to Participant on assignment</li><li>Deadline tracking with overdue alerts</li><li>External ticket sources can auto-create assignments</li></ul>`,

  external_ticket_source: `<h3>How It Works</h3><p>Ingest tickets from external systems (Jira, ServiceNow, property management software) and automatically map them to CaptureSession assignments.</p><h3>User Experience</h3><ul><li>Admin configures integration in settings</li><li>Tickets auto-appear as assignments in dashboard</li><li>Two-way sync: completion status flows back to source</li></ul><h3>Data Flow</h3><p>External webhook/poll → <code>TicketSource { provider, externalId, mappedSchemaId }</code> → auto-create <code>Assignment</code> → Participant notification.</p><h3>Design Decisions</h3><ul><li>Webhook-based for real-time, polling as fallback</li><li>Field mapping configurable per integration</li><li>Bi-directional status sync</li></ul>`,

  self_start: `<h3>How It Works</h3><p>Participant initiates a CaptureSession on their own — selects a Schema, optionally selects a Destination, and begins. Creates a self-assigned Assignment record for tracking.</p><h3>User Experience</h3><ul><li>Tap "Start Capture" in app</li><li>Select Schema from available list</li><li>Optionally select or create Destination</li><li>Begin immediately</li></ul><h3>Data Flow</h3><p>Participant action → <code>Assignment { self: true, schemaId, destinationId? }</code> → <code>CaptureSession</code> created → Capture begins.</p><h3>Design Decisions</h3><ul><li>Ad-hoc Captures not on the schedule</li><li>Follow-up Captures after finding issues</li><li>Training/practice CaptureSessions</li></ul>`,

  inspection_begins: `<h3>How It Works</h3><p>Participant begins the CaptureSession. Selects CaptureMode: site walk (live GPS + photos) or after-the-fact (sitting, upload photos, narrate). System creates a CaptureSession and begins data Capture.</p><h3>User Experience</h3><ul><li>Select CaptureMode (site walk vs after-the-fact)</li><li>AI-guided voice conversation based on Schema Fields</li><li>Progress indicator shows completion percentage</li><li>Can pause and resume</li></ul><h3>Data Flow</h3><p>CaptureMode selection → <code>CaptureSession { orgId, userId, schemaId, assignmentId, mode, status: IN_PROGRESS }</code> → routes to phone or app Capture path.</p><h3>Design Decisions</h3><ul><li>Two CaptureModes cover all scenarios</li><li>CaptureSession is the central tracking entity</li><li>Pause/resume supported for multi-hour CaptureSessions</li></ul>`,

  inspection_mode_selector: `<h3>How It Works</h3><p>Determines data Capture path: site walk mode activates live GPS tracking + real-time photo capture, while after-the-fact mode is optimized for narrating over pre-taken photos.</p><h3>User Experience</h3><ul><li>Simple toggle: "On-Site" vs "After the Fact"</li><li>On-site: GPS tracking starts, camera accessible</li><li>After-fact: photo upload prompt, narration mode</li></ul><h3>Data Flow</h3><p><code>CaptureMode { SITE_WALK, AFTER_FACT }</code> stored on <code>CaptureSession</code>. Routes to phone call path or app Schema path based on selection + device.</p><h3>Design Decisions</h3><ul><li>Two CaptureModes cover 95% of use cases</li><li>CaptureMode selection influences AI Extraction strategy</li><li>Default CaptureMode configurable per org/user</li></ul>`,

  // ── TIER 3 — Capture ──

  calls_twilio: `<h3>How It Works</h3><p>Participant calls the org's Twilio number. Twilio webhook hits the API, which creates a CaptureSession and begins recording + real-time transcription via Media Streams. Schema selection menu guides which Schema to Capture.</p><h3>User Experience</h3><ul><li>Dial org phone number</li><li>Voice menu: select Schema (if multiple assigned)</li><li>AI guides through Schema Fields conversationally</li><li>Text photos to same number during call</li></ul><h3>Data Flow</h3><p>Phone call → Twilio webhook → API → <code>CaptureSession { twilioCallSid }</code> → Media Streams WebSocket → real-time transcription.</p><h3>Design Decisions</h3><ul><li>Twilio Media Streams for real-time audio via WebSocket</li><li>Call recording stored in S3 as backup</li><li>Latency target: <500ms for transcription</li></ul>`,

  realtime_audio: `<h3>How It Works</h3><p>Audio stream from Twilio piped to transcription service in real-time. Transcription chunks arrive every 1–3 seconds with speaker diarization.</p><h3>User Experience</h3><ul><li>Participant speaks naturally — no special commands needed</li><li>AI processes speech in real-time behind the scenes</li><li>Occasional voice prompts guide to next Field</li></ul><h3>Data Flow</h3><p>Twilio MediaStream → WebSocket → Deepgram → <code>TranscriptChunk { text, timestamp, speaker }</code> → buffered for AI Extraction.</p><h3>Design Decisions</h3><ul><li>Deepgram for real-time streaming ($0.0043/min)</li><li>Whisper API for post-processing polish ($0.006/min)</li><li>Speaker diarization + punctuation formatting</li></ul>`,

  opens_app: `<h3>How It Works</h3><p>Participant opens the Expo app, sees their assigned CaptureSessions, selects one, and begins. The app provides a rich step-by-step Schema UI with camera, voice, and GPS Capture. Shows real-time AI mapping feedback.</p><h3>User Experience</h3><ul><li>Open app → see assignment queue</li><li>Select assignment → Schema loads</li><li>Step-by-step UI with Capture buttons</li><li>Real-time Field population preview from AI</li></ul><h3>Data Flow</h3><p>App → API → load <code>Assignment { schemaId, destination }</code> → render <code>Schema { fields[], sections[] }</code>. Real-time Field mapping shows AI progress.</p><h3>Design Decisions</h3><ul><li>Expo SDK with React Native</li><li>Schema rendered from server definition</li><li>Each step can capture text, photo, voice, or signature</li></ul>`,

  voice_camera_gps: `<h3>How It Works</h3><p>Expo app captures voice (on-device STT), photos (with annotations and markup), and GPS coordinates simultaneously. Supports photo markup with circles, arrows, text tags. Auto-captures weather and device info.</p><h3>User Experience</h3><ul><li>Camera button for photos with annotation tools</li><li>Voice button for spoken notes (auto-transcribed)</li><li>GPS auto-tagged to each Capture point</li><li>Markup tools: circle, arrow, text overlay</li></ul><h3>Data Flow</h3><p>Capture → <code>Photo { localUri, gpsLat, gpsLng }</code> + <code>AudioRecording { localUri, duration }</code> → local SQLite → sync queue.</p><h3>Design Decisions</h3><ul><li>Photos captured in context, linked to Schema Fields</li><li>GPS auto-tagged to each Capture point</li><li>On-device STT via native APIs (free, instant)</li></ul>`,

  session_metadata_capture: `<h3>How It Works</h3><p>Automatically captured for every CaptureSession: weather conditions, GPS location trail, timestamps, pause counts, device info. Provides context for AI and audit trail.</p><h3>User Experience</h3><ul><li>Invisible to Participant — fully automatic</li><li>Weather auto-fetched from GPS coordinates</li><li>Timestamps for session start, pauses, completion</li></ul><h3>Data Flow</h3><p>Auto-capture → <code>SessionMeta { sessionId, weather, deviceInfo, pauseCount, gpsTrack[] }</code> → stored as context metadata on <code>FieldExtractions</code>.</p><h3>Design Decisions</h3><ul><li>Zero Participant effort — fully automatic background capture</li><li>Weather API call based on GPS + timestamp</li><li>Metadata available for audit and dispute resolution</li></ul>`,

  photo_markup_tagging: `<h3>How It Works</h3><p>In-app photo annotation tools: draw circles around defects, add arrows pointing to issues, overlay text tags. Caption confirmation toggle lets Participant verify AI-generated captions.</p><h3>User Experience</h3><ul><li>Take photo → markup tools appear</li><li>Draw circles, arrows, text annotations</li><li>AI suggests caption → Participant confirms or edits</li><li>Tags auto-linked to relevant Schema Fields</li></ul><h3>Data Flow</h3><p>Photo → markup → <code>PhotoAnnotation { photoId, type, coordinates, text, color }</code> → sent to photo analysis AI with annotation context.</p><h3>Design Decisions</h3><ul><li>Simple touch-based drawing tools optimized for mobile</li><li>Annotations preserved as separate layer (original photo unchanged)</li><li>Caption confirmation reduces AI hallucination risk</li></ul>`,

  sms_photos: `<h3>How It Works</h3><p>During or after call, Participant texts photos to the Twilio number. Photos are auto-matched to the active CaptureSession via phone number + time window (30 min).</p><h3>User Experience</h3><ul><li>Take photo with regular camera</li><li>Text/MMS to org's Twilio number</li><li>Photos auto-appear in Contract report</li></ul><h3>Data Flow</h3><p>MMS → Twilio webhook → match <code>CaptureSession</code> via phone + 30min window → S3 upload → <code>Photo { captureSessionId, s3Key }</code>.</p><h3>Design Decisions</h3><ul><li>Twilio MMS webhook → S3 upload</li><li>Phone number matching to active CaptureSession</li><li>Multiple photos in one message supported</li></ul>`,

  local_sync: `<h3>How It Works</h3><p>All captured data stored locally in SQLite first. Enables fully offline CaptureSessions — everything syncs when connectivity returns. Background worker handles chunked uploads with resume.</p><h3>User Experience</h3><ul><li>Works offline — no connectivity required during Capture</li><li>Sync status indicator in app</li><li>Auto-syncs when connection restored</li><li>Manual sync button for impatient users</li></ul><h3>Data Flow</h3><p>Capture → <code>CaptureSession { schemaId, fieldExtractions[] }</code> → SQLite → <code>SyncQueue { entity, action }</code> → chunked upload → S3 for media, API for data.</p><h3>Design Decisions</h3><ul><li>expo-sqlite for structured data</li><li>Chunked uploads with resume capability</li><li>Last-write-wins for simple Fields</li><li>Sync status visible in app UI</li></ul>`,

  // ── TIER 4 — Extraction ──

  transcription: `<h3>How It Works</h3><p>All audio — whether from phone call or app recording — is transcribed to text. Real-time streaming for phone calls, batch processing for synced recordings.</p><h3>User Experience</h3><ul><li>Invisible to Participant — happens automatically</li><li>Real-time for phone calls (sub-second latency)</li><li>Batch for uploaded recordings (seconds to minutes)</li></ul><h3>Data Flow</h3><p>AudioStream/File → transcription engine → <code>Transcript { text, segments[], speakers[] }</code> → fed to AI Extraction + OCR resolver.</p><h3>Design Decisions</h3><ul><li>Deepgram: Real-time streaming, $0.0043/min</li><li>Whisper API: Batch, highest accuracy, $0.006/min</li><li>On-device: iOS/Android native, free, variable quality</li></ul>`,

  ai_extraction: `<h3>How It Works</h3><p>GPT-4o or Claude processes the full transcript + photo descriptions + Schema guidance against the Schema. Extracts structured FieldExtractions with confidence scores. Multi-pass Extraction with validation.</p><h3>User Experience</h3><ul><li>Invisible to Participant — results appear as pre-filled Contract</li><li>Confidence scores shown as color indicators</li><li>Low-confidence Fields highlighted for review</li></ul><h3>Data Flow</h3><p>Input: <code>{ transcript, schema, photos, schemaGuidance }</code> → LLM → output: <code>FieldExtraction[] { fieldId, value, confidence: 0–1 }</code> → stored as <code>FieldExtraction</code>.</p><h3>Design Decisions</h3><ul><li>Prompt: Schema + transcript + photo descriptions + guidance markdown</li><li>Multi-pass: extract → validate → resolve ambiguities</li><li>Fallback chain: GPT-4o → Claude → manual</li></ul>`,

  photo_analysis: `<h3>How It Works</h3><p>GPT-4o vision analyzes photos: identifies defects, generates descriptive captions, auto-links to Schema Fields. OCR text extraction from photos. Priority: narration > OCR when conflict detected.</p><h3>User Experience</h3><ul><li>Photos auto-analyzed after upload</li><li>AI-generated captions appear in Contract</li><li>Defects highlighted with severity ratings</li></ul><h3>Data Flow</h3><p>Input: <code>Photo[] { s3Key, context, annotations }</code> → GPT-4o vision → output: <code>{ caption, defects[], linkedFieldIds[], severity, ocrText }</code>.</p><h3>Design Decisions</h3><ul><li>Defect identification (damaged siding, missing insulation)</li><li>Auto-captioning for Contract inclusion</li><li>OCR text passed to narration resolver for conflict detection</li></ul>`,

  ocr_narration_resolver: `<h3>How It Works</h3><p>Compares text extracted via photo OCR with transcript narration. When conflicts exist (Participant says one thing, photo shows another), flags the discrepancy. Prefers narration by default — Participant intent takes priority.</p><h3>User Experience</h3><ul><li>Invisible — runs automatically during Extraction</li><li>Conflicts flagged as yellow indicators in review</li><li>Participant sees both values and chooses correct one</li></ul><h3>Data Flow</h3><p>Input: OCR text + transcript segments → compare → output: <code>{ resolvedValue, conflictFlag, preferredSource }</code>. Narration preferred > OCR by default.</p><h3>Design Decisions</h3><ul><li>Narration priority: Participant spoke intentionally, OCR may misread</li><li>Conflicts surfaced, not auto-resolved</li><li>Configurable preference per org</li></ul>`,

  realtime_field_mapping: `<h3>How It Works</h3><p>During active CaptureSession, AI processes transcript chunks and updates FieldExtractions in near-real-time (~10s refresh). Participant sees Fields populating live in the app.</p><h3>User Experience</h3><ul><li>Schema Fields fill in as Participant speaks</li><li>Refresh button for manual update</li><li>Visual feedback: Field turns green when AI fills it</li></ul><h3>Data Flow</h3><p>TranscriptChunk stream → partial Extraction → <code>FieldExtraction[]</code> partial update → WebSocket push to app UI → live preview.</p><h3>Design Decisions</h3><ul><li>~10 second refresh cadence balances accuracy vs latency</li><li>Partial Extraction — later passes may override earlier values</li><li>Visual feedback motivates thorough narration</li></ul>`,

  confidence_scoring: `<h3>How It Works</h3><p>Multi-pass validation scores each extracted FieldExtraction on a 0–1 confidence scale. Factors in Extraction confidence, normalization confidence from alias resolution, and cross-field consistency.</p><h3>User Experience</h3><ul><li>High confidence (≥0.9): green, auto-accepted</li><li>Medium (0.6–0.9): yellow, flagged for review</li><li>Low (<0.6): red, requires manual entry</li></ul><h3>Data Flow</h3><p>Input: <code>FieldExtraction[] { value, source, normalizationConfidence }</code> → scoring algorithm → output: confidence 0–1 per Field.</p><h3>Design Decisions</h3><ul><li>≥0.9 auto | 0.6–0.9 review | <0.6 manual</li><li>Normalization confidence factors into overall score</li><li>Thresholds configurable per org</li></ul>`,

  quality_validation: `<h3>How It Works</h3><p>Automated checks for data quality: required Fields present, cross-field consistency, format validation, and duplicate detection across recent CaptureSessions.</p><h3>User Experience</h3><ul><li>Validation errors shown as inline warnings</li><li>Missing required Fields highlighted in red</li><li>Cross-field inconsistencies explained in plain text</li></ul><h3>Data Flow</h3><p>Input: <code>FieldExtraction[]</code> + <code>FieldConfig[]</code> → validation rules → output: warnings[], errors[], pass/fail per Field.</p><h3>Design Decisions</h3><ul><li>Required Field completeness check</li><li>Conditional logic validation</li><li>Format validation (dates, numbers, enums)</li><li>Duplicate detection across recent CaptureSessions</li></ul>`,

  form_field_values: `<h3>How It Works</h3><p>All extracted data persisted as FieldExtraction records in PostgreSQL. Each record links to a CaptureSession, Schema, and Field with the extracted value, confidence score, and source tracking. Together they form the Contract.</p><h3>User Experience</h3><ul><li>Participant sees pre-filled Contract with confidence indicators</li><li>Can edit any Field — source changes to "edited"</li><li>Full audit trail of all changes visible</li></ul><h3>Data Flow</h3><p><code>FieldExtraction { id, captureSessionId, fieldId, value: JSON, confidence, source, editedAt }</code>. Sources: ai_extracted, manual_entry, edited, photo_detected, normalized.</p><h3>Design Decisions</h3><ul><li>Value stored as JSON to handle all Field types</li><li>Full audit trail of changes</li><li>Source tracking for AI learning feedback</li></ul>`,

  field_normalization: `<h3>How It Works</h3><p>After AI Extraction, resolve aliases and apply vocabulary packages to standardize values. Converts shorthand, acronyms, and regional terms to canonical forms for consistency.</p><h3>User Experience</h3><ul><li>Invisible — runs automatically after Extraction</li><li>Normalized values shown in review with original in tooltip</li><li>Participant can revert normalization if incorrect</li></ul><h3>Data Flow</h3><p>Input: raw <code>FieldExtraction[]</code> + <code>Alias[]</code> + <code>VocabularyPackage[]</code> → normalize → output: canonical values + normalization confidence.</p><h3>Design Decisions</h3><ul><li>Runs after Extraction, before scoring</li><li>Original value preserved for audit</li><li>Per-org vocabulary packages improve accuracy over time</li></ul>`,

  // ── TIER 5 — Contract Review ──

  inspector_submit: `<h3>How It Works</h3><p>After Extraction completes, the Participant sees the populated Contract with confidence indicators. Reviews, makes corrections to flagged Fields, and submits. Slide-to-complete UX for trusted Participants.</p><h3>User Experience</h3><ul><li>Confidence-sorted Field list (lowest first)</li><li>Side-by-side: AI value vs. transcript excerpt</li><li>One-click approve for high-confidence Fields</li><li>Slide-to-complete for trusted Participant fast path</li></ul><h3>Data Flow</h3><p>Participant reviews <code>FieldExtraction[]</code> → edits low-confidence → submit action → <code>CaptureSession.status</code> → SUBMITTED.</p><h3>Design Decisions</h3><ul><li>Confidence-guided review reduces review time by 60%+</li><li>Slide-to-complete skips review for trusted Participants (configurable)</li><li>All edits tracked with source: "edited"</li></ul>`,

  inspector_review: `<h3>How It Works</h3><p>After submission, Participant or supervisor does a detailed Contract review. Can edit any Field, add notes, and see confidence scores. Available on mobile (in-field) and dashboard (office).</p><h3>User Experience</h3><ul><li>Full Contract view with all Fields and photos</li><li>Edit any Field — changes tracked</li><li>Photo thumbnails linked to relevant Fields</li><li>Validate button to advance</li></ul><h3>Data Flow</h3><p>Display <code>FieldExtraction[]</code> with confidence flags → allow edits → <code>FieldExtraction.source: edited</code> → validate → <code>CaptureSession.status: VALIDATED</code>.</p><h3>Design Decisions</h3><ul><li>Participant is final authority — can override any AI Extraction</li><li>Photo thumbnails linked to relevant Fields</li><li>Available on both mobile and desktop</li></ul>`,

  mobile_infield_review: `<h3>How It Works</h3><p>Supervisor reviews, edits, and approves Contracts directly from the mobile app while still in the field. Enables same-day turnaround without returning to office.</p><h3>User Experience</h3><ul><li>Push notification: "New Contract ready for review"</li><li>Full Contract view in app with edit capability</li><li>Approve or request changes with one tap</li></ul><h3>Data Flow</h3><p>Push notification → open Contract → review <code>FieldExtraction[]</code> → edit/approve → advance to multi-approval or final sign-off.</p><h3>Design Decisions</h3><ul><li>Same review UI as desktop, optimized for mobile</li><li>Supervisor role required</li><li>Offline review with sync on reconnect</li></ul>`,

  auto_complete_upload: `<h3>How It Works</h3><p>Slide-to-complete gesture triggers instant upload and optionally skips the review queue entirely. For trusted Participants with high historical accuracy, this enables zero-friction completion.</p><h3>User Experience</h3><ul><li>Slide gesture at bottom of completed Schema</li><li>Instant upload begins</li><li>If skip-review enabled: goes directly to Fulfillment</li></ul><h3>Data Flow</h3><p>Slide-to-complete → upload all <code>FieldExtraction[]</code> + media → if <code>org.skipReview: true</code> → bypass review → trigger Fulfillment pipeline.</p><h3>Design Decisions</h3><ul><li>Skip-review is per-org setting, admin-controlled</li><li>Only for Participants with >90% historical accuracy</li><li>Audit trail maintained even when review skipped</li></ul>`,

  multi_approval: `<h3>How It Works</h3><p>Multi-level approval workflow for enterprise compliance: Participant submits → Supervisor reviews → Admin approves → Client receives. Each level can request changes.</p><h3>User Experience</h3><ul><li>Each approver sees what changed since last approval</li><li>Reject sends back with comments for revision</li><li>Approval timestamps for compliance audit trail</li></ul><h3>Data Flow</h3><p><code>Approval { captureSessionId, level, approverId, status, comments }</code> → chain advances → final level triggers Fulfillment.</p><h3>Design Decisions</h3><ul><li>Configurable approval chain per org</li><li>Reject sends back with comments for revision</li><li>Approval timestamps for compliance audit trail</li></ul>`,

  final_signoff: `<h3>How It Works</h3><p>Last approval in the chain triggers the Fulfillment pipeline. CaptureSession status moves to VALIDATED, which enqueues SQS jobs for PDF generation, email delivery, and portal publishing.</p><h3>User Experience</h3><ul><li>Final approver clicks "Sign Off"</li><li>Confirmation with summary of what will be Fulfilled</li><li>ContractStatus changes to VALIDATED in real-time</li></ul><h3>Data Flow</h3><p>Approval → <code>CaptureSession.status: VALIDATED</code> → SQS jobs: PDF generation, email delivery, webhook events, portal update.</p><h3>Design Decisions</h3><ul><li>PDF generation job</li><li>Email delivery job</li><li>Dashboard update (real-time via WebSocket)</li><li>Webhook events to integrations</li></ul>`,

  // ── TIER 6 — Fulfillment ──

  branded_pdf: `<h3>How It Works</h3><p>Structured Contract data + photos compiled into a professional branded PDF report. Standard PAX template or custom per-org with brand upload, Field placement, and layout editor.</p><h3>User Experience</h3><ul><li>Auto-generated after final sign-off</li><li>Admin can customize template with org branding</li><li>Photos embedded with AI-generated captions</li></ul><h3>Data Flow</h3><p>Input: <code>FieldExtraction[]</code> + <code>Photo[]</code> + <code>OutputTemplate</code> → PDF engine → branded PDF → S3 storage → Fulfillment.</p><h3>Design Decisions</h3><ul><li>PDF generation via Puppeteer or react-pdf</li><li>Template per Schema type, branded per org</li><li>Photos embedded with AI-generated captions</li></ul>`,

  pdf_autofill: `<h3>How It Works</h3><p>AI maps FieldExtractions to fields in existing PDF forms (government compliance, client templates). Uses pdf-lib to write into form fields automatically.</p><h3>User Experience</h3><ul><li>Upload target PDF template once</li><li>AI learns field mapping automatically</li><li>Filled PDFs generated alongside branded reports</li></ul><h3>Data Flow</h3><p>Input: <code>FieldExtraction[]</code> + target PDF template → AI field mapping → pdf-lib → filled PDF output.</p><h3>Design Decisions</h3><ul><li>Saves hours of manual data entry for compliance</li><li>AI mapping with human verification on first use</li><li>Supports government and industry-standard PDF forms</li></ul>`,

  output_template_manager: `<h3>How It Works</h3><p>Manage PDF report templates: standard PAX template plus custom per-org templates. Admin uploads brand assets, places Fields on the layout, and previews output.</p><h3>User Experience</h3><ul><li>WYSIWYG template editor</li><li>Upload logo, set colors, choose fonts</li><li>Drag Schema Fields onto template layout</li><li>Preview with sample data</li></ul><h3>Data Flow</h3><p><code>OutputTemplate { orgId, layout, brandAssets, fieldPlacements[] }</code> → used by PDF generation engine at Fulfillment time.</p><h3>Design Decisions</h3><ul><li>Standard PAX template as default fallback</li><li>Custom templates for enterprise branding</li><li>Field placement drives PDF generation layout</li></ul>`,

  external_system_export: `<h3>How It Works</h3><p>Fulfill Contract data to external systems: JSON/CSV download, webhook delivery to Salesforce/ServiceNow, and visible API endpoints with delivery status tracking.</p><h3>User Experience</h3><ul><li>One-click CSV/JSON export from dashboard</li><li>Auto-delivery via configured webhooks</li><li>Delivery status visible: pending, delivered, failed</li></ul><h3>Data Flow</h3><p><code>ExportJob { sessionId, targetSystem, format, status }</code> → transform data → deliver → track status → retry on failure.</p><h3>Design Decisions</h3><ul><li>Multiple format support: CSV, JSON, PDF, webhook</li><li>Delivery status tracking with retry logic</li><li>Field mapping configurable per export target</li></ul>`,

  data_flow_configuration: `<h3>How It Works</h3><p>Visual drag-and-drop interface for admins to map Schema Fields to output targets. Self-serve configuration without developer involvement. Supports transformations and conditional routing.</p><h3>User Experience</h3><ul><li>Visual flow editor: drag Fields → output targets</li><li>Add transformations (date format, unit conversion)</li><li>Conditional routing based on Field values</li><li>Test with sample data before activating</li></ul><h3>Data Flow</h3><p><code>DataFlowMap { schemaId, fieldId, outputTarget, transformation }</code> → executed at Fulfillment time → routes data to configured Destinations.</p><h3>Design Decisions</h3><ul><li>Visual editor for non-technical admins</li><li>Transformation pipeline for data formatting</li><li>Conditional routing for complex output requirements</li></ul>`,

  email_ses: `<h3>How It Works</h3><p>Contracts Fulfilled via SES with branded email templates and PDF attachment. Per-org configuration for recipient lists and delivery triggers.</p><h3>User Experience</h3><ul><li>Automatic Fulfillment after final sign-off</li><li>Branded email with inline summary</li><li>PDF report attached</li><li>Delivery confirmation in dashboard</li></ul><h3>Data Flow</h3><p>SQS job → load <code>Org.emailTemplate</code> → attach PDF → SES send to <code>Person[] { type: CLIENT }</code> → delivery status tracked.</p><h3>Design Decisions</h3><ul><li>AWS SES for reliable delivery</li><li>Branded HTML template per org</li><li>PDF attachment + inline summary</li></ul>`,

  dashboard: `<h3>How It Works</h3><p>Contracts visible instantly in the admin dashboard. Full search, filtering, and export. Real-time updates via WebSocket. Contract browser, assignment tracker, integration status, AI learning feedback.</p><h3>User Experience</h3><ul><li>Real-time CaptureSession list with status filters</li><li>Search by date, Participant, Destination, status</li><li>Bulk actions: validate, export, reassign</li><li>Integration health and AI accuracy metrics</li></ul><h3>Data Flow</h3><p>WebSocket → real-time <code>CaptureSession[]</code> updates → dashboard renders. Search queries via API. Bulk actions dispatch to relevant services.</p><h3>Design Decisions</h3><ul><li>Real-time updates via WebSocket</li><li>Bulk actions for efficiency</li><li>Analytics: completion rates, turnaround times, AI accuracy</li></ul>`,

  client_portal: `<h3>How It Works</h3><p>White-labeled read-only portal for clients to view Contracts. Separate auth context. Webhook/API for programmatic integrations. Webhook delivery status tracking visible to admin.</p><h3>User Experience</h3><ul><li>Client logs in to branded portal</li><li>Sees Contracts for their Destinations</li><li>Downloads PDF reports</li><li>Comments and re-Capture requests</li></ul><h3>Data Flow</h3><p>Client auth → <code>Person { type: CLIENT }</code> → filtered <code>CaptureSession[]</code> view → PDF download. Webhooks: <code>contract.fulfilled</code> event.</p><h3>Design Decisions</h3><ul><li>Major differentiator vs competitors who just email PDFs</li><li>Drives retention through platform stickiness</li><li>Webhook delivery status tracking for reliability</li></ul>`,

  // ── TIER 7 — Intelligence ──

  predictive_analytics: `<h3>How It Works</h3><p>AI analyzes historical CaptureSession data to predict maintenance needs, compliance risks, and cost estimates. Turns raw Contract data into actionable intelligence.</p><h3>User Experience</h3><ul><li>Risk scores per Destination on dashboard</li><li>Predicted maintenance timelines</li><li>Cost estimates for proactive repairs</li></ul><h3>Data Flow</h3><p>Historical <code>CaptureSession[]</code> + <code>FieldExtraction[]</code> → ML pipeline → <code>RiskScore { destinationId, score, factors[] }</code> → dashboard visualization.</p><h3>Design Decisions</h3><ul><li>Requires significant data volume across many CaptureSessions</li><li>Differentiator at scale — competitors don't offer this</li><li>ML models improve with AI Learning Pipeline corrections</li></ul>`,

  insights_dashboard: `<h3>How It Works</h3><p>Dashboard for trends, risk scoring, and maintenance predictions. Org admins see patterns across all CaptureSessions — common defects, seasonal trends, Participant performance.</p><h3>User Experience</h3><ul><li>Charts: defect frequency over time</li><li>Heatmaps: issues by Destination/region</li><li>Participant performance metrics</li><li>Seasonal trend analysis</li></ul><h3>Data Flow</h3><p>Aggregated <code>FieldExtraction[]</code> + <code>RiskScore[]</code> → analytics engine → charts and visualizations → dashboard.</p><h3>Design Decisions</h3><ul><li>Built on same dashboard infrastructure</li><li>Export to CSV/PDF for stakeholder reports</li><li>Role-based: admins see all, Participants see own metrics</li></ul>`,

  ai_learning_pipeline: `<h3>How It Works</h3><p>Captures every Participant correction (AI value → corrected value) and feeds it back to improve Extraction and captioning models. Per-org learning means the system gets smarter for each customer.</p><h3>User Experience</h3><ul><li>Invisible to Participant — corrections auto-captured</li><li>Admin sees AI accuracy metrics in dashboard</li><li>Accuracy improves over time per org</li></ul><h3>Data Flow</h3><p><code>ParticipantCorrection { sessionId, fieldId, aiValue, correctedValue }</code> → training data → fine-tuned prompts → improved Extraction accuracy.</p><h3>Design Decisions</h3><ul><li>Per-org learning for domain-specific improvement</li><li>Corrections feed into prompt engineering, not model fine-tuning (initially)</li><li>Accuracy metrics tracked per Schema type</li></ul>`,

  push_notification_service: `<h3>How It Works</h3><p>Push notifications for key events: new assignments, review requests, approval status changes, completion confirmations. Expo push notification service integration.</p><h3>User Experience</h3><ul><li>Instant notification on new assignment</li><li>Review request notifications for supervisors</li><li>Completion confirmation for admins</li><li>Configurable notification preferences</li></ul><h3>Data Flow</h3><p>Event trigger → lookup <code>PushToken { userId, deviceToken, platform }</code> → Expo Push API → device notification.</p><h3>Design Decisions</h3><ul><li>Expo Push Notifications for cross-platform support</li><li>User-configurable notification preferences</li><li>Batched delivery to avoid notification fatigue</li></ul>`,

  feedback_loop: `<h3>How It Works</h3><p>Clients comment on Contracts, request re-Captures, or flag issues. Re-Capture requests create new assignments linked to the original. Captures corrections for AI retraining.</p><h3>User Experience</h3><ul><li>Client comments in portal → admin notification</li><li>Re-Capture request → new assignment auto-created</li><li>Feedback visible in Contract timeline</li></ul><h3>Data Flow</h3><p><code>Comment { captureSessionId, text }</code> → notification. Re-Capture request → <code>Assignment { originalCaptureSessionId }</code> → new Capture cycle. Corrections → AI Learning Pipeline.</p><h3>Design Decisions</h3><ul><li>Comment → Notification to admin</li><li>Re-Capture request → New Assignment linked to original</li><li>Pattern feedback → Improve AI Extraction</li></ul>`,

};
